CREATE TABLE IF NOT EXISTS page_classifications(id uuid PRIMARY KEY,domain_id uuid NOT NULL REFERENCES domains(id) ON DELETE CASCADE,page_id uuid REFERENCES pages(id) ON DELETE CASCADE,class text NOT NULL,confidence double precision NOT NULL DEFAULT 0,evidence jsonb NOT NULL DEFAULT '[]',source_url text NOT NULL DEFAULT '',detected_at timestamptz NOT NULL DEFAULT now(),UNIQUE(domain_id,page_id,class));
CREATE TABLE IF NOT EXISTS business_profiles(id uuid PRIMARY KEY,domain_id uuid NOT NULL REFERENCES domains(id) ON DELETE CASCADE,name text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',source_url text NOT NULL DEFAULT '',confidence double precision NOT NULL DEFAULT 0,detected_at timestamptz NOT NULL DEFAULT now(),UNIQUE(domain_id));
CREATE TABLE IF NOT EXISTS social_profiles(id uuid PRIMARY KEY,domain_id uuid NOT NULL REFERENCES domains(id) ON DELETE CASCADE,network text NOT NULL,url text NOT NULL,normalized_url text NOT NULL,source_url text NOT NULL DEFAULT '',confidence double precision NOT NULL DEFAULT 0,detected_at timestamptz NOT NULL DEFAULT now(),UNIQUE(domain_id,network,normalized_url));
CREATE INDEX IF NOT EXISTS page_classifications_lookup ON page_classifications(domain_id,class);
CREATE INDEX IF NOT EXISTS social_profiles_lookup ON social_profiles(domain_id,network);
